WITH filtered_transactions AS (SELECT * FROM transactions WHERE txn_type = 'CREDIT' AND account_id IN (3, 12, 34, 37)), txn_hour_summary AS (SELECT HOUR(txn_time) AS txn_hour, SUM(CASE WHEN merchant = 'Shell' THEN 1 ELSE 0 END) AS shell_count, MIN(txn_time) AS min_txn_time FROM filtered_transactions GROUP BY HOUR(txn_time)) SELECT txn_hour, shell_count, min_txn_time FROM txn_hour_summary WHERE shell_count >= 24 ORDER BY min_txn_time DESC, txn_hour LIMIT 3
